func TestCalculate(t *testing.T) {
	a := &state.Application{Income: 100}
	Calculate(a)
	if a.Limit != 400 {
		t.Fatal(a.Limit)
	}
}

func Calculate(a *state.Application) {
	a.Limit = a.Income * 6
	if a.Debt*100 > a.Income*40 {
		a.Limit = 0
		a.Codes = append(a.Codes, RuleDebt)
	}
	state.ApplyIncomeCap(a)
}

func Evaluate(a *state.Application) {
	if a.Product == "consumer" {
		consumer.Calculate(a)
	} else {
		refinance.Calculate(a)
	}
	a.Limit = min(a.Limit, 100000)
	state.Finalize(a, consumer.Policy{Limit: 90000}, func(a *state.Application) { a.Limit -= 100 })
}
